                    dp[i] = max(dp[i], dp[j] + 1)
        return max(dp)

    # Function to find the length of the longest decreasing subsequence
    def lds(arr):
        dp = [1] * n
        for i in range(n-2, -1, -1):
            for j in range(i+1, n):
                if arr[i] >= arr[j]:
                    dp[i] = max(dp[i], dp[j] + 1)
        return max(dp)

    # Calculate LIS and LDS
